// Build kulturenEssay blocks from the { s, t } paragraph list.
function buildEssay(slug, paras) {
  return paras.map((p, i) => mdBlock(`${slug}-ke${i}`, p.s, p.t))
}

// Build kulturenSidebar boxes (notes + timelines) from the sidebar list.
function buildSidebar(slug, boxes) {
  return boxes.map((b, i) => {
    const key = `${slug}-ks${i}`
    if (b.timeline) {
      return {
        _type: 'kulturenTimeline',
        _key: key,
        label: b.label,
        entries: b.timeline.map((row, j) => ({
          _type: 'kulturenTimelineEntry',
          _key: `${key}-t${j}`,
          year: row[0],
          text: mdInline(`${key}-t${j}`, row[1]),
        })),
      }
    }
    const valArr = Array.isArray(b.value) ? b.value : [b.value]
    return {
      _type: 'kulturenSideNote',
      _key: key,
      label: b.label,
      emphasis: b.cash ? 'cash' : 'default',
      value: valArr.map((t, j) => mdBlock(`${key}-v${j}`, 'normal', t)),
    }
  })
}

// Empty "posts" placeholder — identical across landscapes except the bold
// display name (para 1) and the roman numeral (para 2 + primary action).
function emptyState(item, fullName) {
  const s = item.slug
  return {
    emptyMeta: '0 indlæg · arkivet åbnes',
    emptyLabel: '— ingen indlæg endnu —',
    emptyHeading: inline(`${s}-eh`, [
      span(`${s}-eh-a`, 'Arkivet '),
      span(`${s}-eh-b`, 'åbner', ['em']),
      span(`${s}-eh-c`, ' her.'),
    ]),
    emptyBody: [
      block(`${s}-eb1`, [
        span(`${s}-eb1-a`, 'Det her er hjørnet, hvor blogposter, anmeldelser, fund og fodnoter om '),
        span(`${s}-eb1-b`, fullName, ['strong']),
        span(`${s}-eb1-c`, ' vil samles. Det er bevidst tomt nu — siden er en notesbog, der vokser, og dette landskab venter sin første indførsel.'),
      ]),
      block(`${s}-eb2`, [
        span(`${s}-eb2-a`, 'Indtil da: introduktionen på '),
        span(`${s}-eb2-b`, 'Kulturen', ['em']),
        span(`${s}-eb2-c`, `-siden tegner landskabets omrids. Klik tilbage og læs Landskab ${item.rn}, eller gå videre til et af de andre syv arkiver herunder.`),
      ]),
    ],
    emptyActions: [
      { _key: `${s}-a1`, _type: 'object', text: `← Til Landskab ${item.rn} på Kulturen`, href: `/kulturen#${s}`, style: 'primary' },
      { _key: `${s}-a2`, _type: 'object', text: 'Bøger, spil & film', href: '/boeger-spil-film', style: 'secondary' },
    ],
  }
}

// Identity + hero + empty state + Kulturen .land section + seo for one landscape.
function fullDoc(item) {
  const c = CONTENT[item.slug]
  const k = KULTUREN[item.slug]
  return {
    ...identityDoc(item),
    eyebrow: c.eyebrow,
    motto: c.motto,
    deck: inline(`${item.slug}-deck`, [span(`${item.slug}-deck-a`, c.deck)]),
    topicsLabel: 'Emner:',
    topics: c.topics,
    crumbBackText: '← Kulturen',
    crumbBackHref: '/kulturen',
    ...emptyState(item, c.fullName),
    kulturenBgVariant: k.bg,
    kulturenEssay: buildEssay(item.slug, k.essay),
    kulturenSidebar: buildSidebar(item.slug, k.sidebar),
    kulturenArchiveCta: k.cta,
    kulturenCardTag: k.cardTag,
    seo: {
      title: `${c.fullName} — Kulturen · Johnny og jeg`,
      description: c.seoDescription,
    },
  }
}

const docs = IDENTITY.map(fullDoc)

async function main() {
  const tx = docs.reduce((t, doc) => t.createOrReplace(doc), client.transaction())
  await tx.commit()
  console.log(`Seeded ${docs.length} landscape documents:`, docs.map((d) => d._id).join(', '))
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})
